# Let me determine the exact mapping from input to output
# by looking at which input cells contribute to which output cells

def analyze_mapping(in_grid, out_grid):
    """Find which input cells map to each output cell"""
    mapping = {}
    # For each output cell, find contributing input cells
    for ri in range(len(out_grid)):
        for ci in range(len(out_grid[0])):
            val = out_grid[ri][ci]
            contributions = []
            for r in range(len(in_grid)):
                for c in range(len(in_grid[0])):
                    if in_grid[r][c] == val:
                        contributions.append((r, c))
            mapping[(ri, ci)] = set(contributions)
    return mapping

mapping = analyze_mapping(
    [[1, 0, 0, 0, 9],
